<?php /** @var array $data */ ?>
<div class="page-header"><div><h1>Report Cards</h1><p><?=htmlspecialchars($data['exam']['name']??'Examination')?> — published student statements</p></div></div>
<div class="card" style="margin-bottom:1rem"><form method="post" action="/exams/<?= (int)$data['exam']['id']?>/report-cards/generate"><input type="hidden" name="_token" value="<?=htmlspecialchars(csrf_token())?>"><button type="submit">Generate Report Cards</button></form></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Admission No.</th><th>Student</th><th>Status</th><th>Attendance</th><th>Actions</th></tr></thead><tbody><?php foreach($data['cards'] as $card): ?><tr><td><?=htmlspecialchars($card['admission_no'])?></td><td><?=htmlspecialchars(trim($card['first_name'].' '.$card['middle_name'].' '.$card['last_name']))?></td><td><?=htmlspecialchars(ucfirst($card['status']))?></td><td><?= (int)$card['attendance_present']?> present / <?= (int)$card['attendance_absent']?> absent</td><td><?php if($card['status']!=='published'): ?><form method="post" action="/exams/<?= (int)$data['exam']['id']?>/report-cards/publish" style="display:inline"><input type="hidden" name="_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="card_id" value="<?= (int)$card['id']?>"><button type="submit">Publish</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
